#!/usr/bin/env node
// Fetches real Wikipedia photos for every built-in ChronoMap place and
// writes them to src/data/placeImages.generated.js, which the client
// overlays onto src/data/places.js (see src/context/PlacesContext.jsx).
//
// Run this once from the server/ folder, with internet access:
//   node scripts/sync-place-images.mjs
//
// Safe to re-run any time (e.g. after adding a place to
// src/data/placeImageTopics.js) -- it always looks up every topic fresh and
// overwrites the generated file. It never touches src/data/places.js
// itself. A place that can't be resolved (network hiccup, no matching
// article) simply keeps whatever image it already has -- nothing on the
// site is ever left broken by a failed run.
import { fileURLToPath } from 'node:url'
import path from 'node:path'
import fs from 'node:fs/promises'
import { fetchPlaceImageSet } from '../src/utils/wikimediaImages.js'
import { PLACE_IMAGE_TOPICS } from '../../src/data/placeImageTopics.js'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const PLACES_FILE = path.resolve(__dirname, '../../src/data/places.js')
const OUT_FILE = path.resolve(__dirname, '../../src/data/placeImages.generated.js')

// src/data/places.js imports .jpg/.png files (fine for Vite, the app's own
// bundler) -- but this script runs under plain Node, which has no loader for
// image files and would crash on that import. Every place object there
// follows `id: '...'` immediately followed by `name: '...'`, so the display
// names are pulled out with a regex instead of importing/executing the file.
async function readPlaceNames() {
  const text = await fs.readFile(PLACES_FILE, 'utf8')
  const names = new Map()
  // Anchored to a 4-space indent so this only matches a top-level place's
  // own id/name (8-space nested entries, like a keyFigures person, are
  // skipped). Handles both quote styles actually used in the file (the
  // first entry uses single quotes, the rest use double).
  const re = /^ {4}id: +(['"])((?:(?!\1).)+)\1,\s*\n {4}name: +(['"])((?:(?!\3).)+)\3/gm
  let match
  while ((match = re.exec(text))) names.set(match[2], match[4])
  return names
}
const GALLERY_SIZE = 6
// Be polite to Wikipedia's shared infrastructure -- this script makes
// 3-4 requests per place, so a small gap between places keeps the burst
// rate well under anything that would look like abuse.
const DELAY_MS = 200

const sleep = (ms) => new Promise((r) => setTimeout(r, ms))

async function main() {
  const placeNames = await readPlaceNames()
  const ids = Object.keys(PLACE_IMAGE_TOPICS)

  const results = {}
  const warnings = []
  let ok = 0

  for (const [i, id] of ids.entries()) {
    const topic = PLACE_IMAGE_TOPICS[id]
    const name = placeNames.get(id) || topic.title
    process.stdout.write(`[${i + 1}/${ids.length}] ${name} (${topic.title})... `)
    let set
    try {
      set = await fetchPlaceImageSet(topic, name, GALLERY_SIZE)
    } catch (err) {
      set = { image: null, gallery: [], warning: `Unexpected error: ${err.message}` }
    }
    if (set.image) {
      results[id] = { image: set.image, gallery: set.gallery }
      ok += 1
      console.log(`ok (${set.gallery.length} photos)${set.warning ? ` -- ${set.warning}` : ''}`)
    } else {
      console.log(`SKIPPED -- ${set.warning}`)
    }
    if (set.warning) warnings.push(`${id}: ${set.warning}`)
    await sleep(DELAY_MS)
  }

  const header = `// AUTO-GENERATED by server/scripts/sync-place-images.mjs -- do not hand-edit.
// Regenerate with:  node scripts/sync-place-images.mjs   (run from server/)
//
// Real photos pulled from Wikipedia, keyed by place id. Overlaid onto the
// static dataset in src/data/places.js at runtime -- see
// src/context/PlacesContext.jsx. A place id missing from this file just
// keeps whatever image src/data/places.js already gives it.
//
// Generated ${new Date().toISOString()} -- ${ok}/${ids.length} places resolved.
`
  const body = `export const PLACE_IMAGE_OVERRIDES = ${JSON.stringify(results, null, 2)}\n`
  await fs.writeFile(OUT_FILE, header + body)

  console.log(`\n${ok}/${ids.length} places updated -> ${path.relative(process.cwd(), OUT_FILE)}`)
  if (warnings.length) {
    console.log(`\n${warnings.length} warning(s):`)
    for (const w of warnings) console.log(`  - ${w}`)
  }
  if (ok < ids.length) {
    console.log(
      `\n${ids.length - ok} place(s) were skipped and keep their previous image. Re-run this script to retry them` +
        ' (a transient network error is the most common cause), or adjust the topic in src/data/placeImageTopics.js if a title is wrong.'
    )
  }
}

main().catch((err) => {
  console.error('Sync failed:', err)
  process.exitCode = 1
})
